-- 452_hidden_curated_2.sql — #452 Riverside story batch, part 2: 14 HIDDEN storyless pins from the gate-drops/leads union
-- brought back with a story (drafted 2026-11-03). Same shape and rules as 452_hidden_curated.sql: exact stored name at the
-- stored coordinate; every pin passed #542 by pin id; every story read from its source (HMdb markers, the City of Riverside's
-- public-art list, Wikipedia, UCR Library, ODMP) and checked against it. One more rescue, the Highgrove hydroelectric plant
-- marker (hidden as "Riverside Canal County Landmark", osm_node14178532350), FAILS #542 — stored only in 680_-2346, never its
-- containing tile 680_-2347 — so it is a `new` seed line in names-452-riverside-2.txt instead. Verdicts for all 120 union
-- rows are in 452_gate_drops_riverside.tsv / 452_leads_riverside.tsv. Batch file — run in the Mac session after the seed
-- commit, together with 452_hidden_curated.sql, then curated_category_backfill(true); each row should report dist_m 0.
with v(name, lat, lng, description, source_url, note) as (values
  ($t$National POW/MIA Memorial$t$, 33.8872156::double precision, -117.2780826::double precision, $t$This memorial honors the hundreds of thousands of Americans held as prisoners of war, and those still missing in action, since the American Revolution; President George W. Bush declared it the National Prisoner of War/Missing in Action Memorial on December 10, 2004.$t$, $t$https://www.hmdb.org/m.asp?m=54380$t$, $t$#452 hidden-pin row: osm_node1299483990, stored in 678_-2345, 678_-2346; containing tile 678_-2346 stores it (#542)$t$),
  ($t$De Anza Statue$t$, 33.976347::double precision, -117.3795979::double precision, $t$Juan Bautista de Anza, the first European known to have visited what is now Riverside, passed through in 1774 and again in 1775-76 seeking an overland route from Sonora to San Francisco Bay; the Works Projects Administration sponsored this statue in 1940, modeled by Ed J. Loustanuau, a descendant of de Anza's brother.$t$, $t$https://www.hmdb.org/m.asp?m=304231$t$, $t$#452 hidden-pin row: osm_node5903058793, stored in 679_-2347, 679_-2348, 680_-2347, 680_-2348; containing tile 680_-2348 stores it (#542)$t$),
  ($t$Staff Sergeant Ysmael R. Villegas$t$, 33.9800266::double precision, -117.3755051::double precision, $t$Ysmael "Smiley" Villegas, born and raised in Riverside, was an Army squad leader in the Philippines; on March 20, 1945, a day before his 21st birthday, he charged enemy positions again and again to draw fire from his squad and was killed, becoming Riverside County's first Medal of Honor recipient. The statue was erected in 1995.$t$, $t$https://www.hmdb.org/m.asp?m=226089$t$, $t$#452 hidden-pin row: osm_node6517171557, stored in 679_-2347, 679_-2348, 680_-2347, 680_-2348; containing tile 680_-2348 stores it (#542)$t$),
  ($t$World War II Water Buffalo Tank$t$, 33.9968487::double precision, -117.3810343::double precision, $t$Riverside built these amphibious tractors: in World War II the Food Machinery Corporation, a maker of farm equipment and insecticide spray pumps, turned out Landing Vehicles, Tracked at four plants, Riverside among them, and its improved LVT-2 was nicknamed the Water Buffalo.$t$, $t$https://en.wikipedia.org/wiki/Landing_Vehicle,_Tracked$t$, $t$#452 hidden-pin row: osm_node5373724241, stored in 680_-2347, 680_-2348; containing tile 680_-2348 stores it (#542)$t$),
  ($t$Mahatma Gandhi$t$, 33.9827109::double precision, -117.3739313::double precision, $t$Madan and Aruna Garge's 2005 bronze, the Tower of Human Values, shows Mahatma Gandhi standing, with the faces of other inspirational figures engraved at its base.$t$, $t$https://riversideca.gov/cedd/arts-cultural-affairs/art/public-art-list-location$t$, $t$#452 hidden-pin row: osm_node6517185380, stored in 680_-2347, 680_-2348; containing tile 680_-2347 stores it (#542)$t$),
  ($t$Cesar E. Chavez$t$, 33.9817971::double precision, -117.3746736::double precision, $t$Ignacio Gomez's statue of Cesar Chavez leading the way honors the farmworker leader and his movement for the human rights of the poor and mistreated; dedicated on June 8, 2013, it completed the peace walk along the downtown Main Street mall.$t$, $t$https://www.hmdb.org/m.asp?m=304168$t$, $t$#452 hidden-pin row: osm_node6517185381, stored in 680_-2347, 680_-2348; containing tile 680_-2347 stores it (#542)$t$),
  ($t$Dosan Ahn Chang-Ho$t$, 33.9820817::double precision, -117.3743223::double precision, $t$Korean independence leader Ahn Chang-Ho came to America in 1902 and is honored here as pioneer, educator, orange picker and patriot; seeing Hawaii's peaks from his steamship, he took the name Dosan, Island Mountain, resolving to stand above the turmoil Imperial Japan had brought to Korea.$t$, $t$https://www.hmdb.org/m.asp?m=304173$t$, $t$#452 hidden-pin row: osm_node6517185383, stored in 680_-2347, 680_-2348; containing tile 680_-2347 stores it (#542)$t$),
  ($t$Sower's Dream$t$, 33.9837536::double precision, -117.3733586::double precision, $t$Sower's Dream honors Eliza Tibbets, abolitionist, suffragist and citrus pioneer, who in 1877 planted two navel orange trees from Bahia, Brazil in her Riverside garden and nourished them with leftover dishwater, starting an industry that by 1897 made Riverside the wealthiest city per capita in the country.$t$, $t$https://www.hmdb.org/m.asp?m=304319$t$, $t$#452 hidden-pin row: osm_node6517187740, stored in 680_-2347, 680_-2348; containing tile 680_-2347 stores it (#542)$t$),
  ($t$California Citrus State Historic Park$t$, 33.8961617::double precision, -117.4183255::double precision, $t$Established in 1993, this 248-acre state park keeps working groves and a museum to tell the story of the time when "Citrus was King" in California, especially Riverside's navel orange, through the migrant and immigrant groups who built the industry.$t$, $t$https://en.wikipedia.org/wiki/California_Citrus_State_Historic_Park$t$, $t$#452 hidden-pin row: osm_way44486177, stored in 677_-2348, 678_-2348, 678_-2349; containing tile 678_-2348 stores it (#542)$t$),
  ($t$Santa Fe Depot$t$, 33.9793087::double precision, -117.3674515::double precision, $t$C.S. Gilman and M.R. Mohr of Los Angeles designed this Pueblo Revival depot, a style the Santa Fe favored across the Southwest, to replace an earlier wood-frame Victorian station on the same site; the last scheduled passenger train, the Grand Canyon Special to Los Angeles, left on May 15, 1968.$t$, $t$https://www.hmdb.org/m.asp?m=303755$t$, $t$#452 hidden-pin row: osm_way125135482, stored in 679_-2347, 680_-2347, 680_-2348; containing tile 680_-2347 stores it (#542)$t$),
  ($t$Dr. Martin Luther King Jr.$t$, 33.9810919::double precision, -117.3750807::double precision, $t$Lisa Reinertson's 1999 "I Have a Dream" sculpture, the heart of the city's Martin Luther King Jr. Memorial, shows King striding forward with two young children under his arms, his words etched into the granite pavement around him.$t$, $t$https://publicartinpublicplaces.blogspot.com/2020/01/martin-luther-king-jr-memorials-and.html$t$, $t$#452 hidden-pin row: osm_node6517185379, stored in 679_-2347, 679_-2348, 680_-2347, 680_-2348; containing tile 680_-2348 stores it (#542)$t$),
  ($t$Officer Leonard Christiansen and Officer Paul Teel Memorial$t$, 33.9802408::double precision, -117.3755802::double precision, $t$Riverside police officers Leonard Christiansen and Paul Teel were shot and killed in an ambush on April 2, 1971, after the suspects called in a fake burglary report at an abandoned house.$t$, $t$https://odmp.org/officer/13162-police-officer-paul-c-teel$t$, $t$#452 hidden-pin row: osm_node7278267579, stored in 679_-2347, 679_-2348, 680_-2347, 680_-2348; containing tile 680_-2348 stores it (#542)$t$),
  ($t$Big 'C'$t$, 33.9713253::double precision, -117.3022879::double precision, $t$UC Riverside students built this concrete "C" on Box Springs Mountain in August 1955; 132 feet long, it is billed as the largest concrete block letter on record, bigger than the "C" at any other UC campus.$t$, $t$https://library.ucr.edu/node/966$t$, $t$#452 hidden-pin row: osm_way1125736897, stored in 679_-2346, 680_-2346; containing tile 679_-2346 stores it (#542)$t$),
  ($t$The Center for Social Justice & Civil Liberties$t$, 33.9821342::double precision, -117.3764064::double precision, $t$This 1926 Churrigueresque building by Stiles O. Clements once housed Citrus Belt Savings and Loan; Riverside Community College District bought it in 2005 meaning to tear it down, restored it instead, and opened the museum here in 2012 around the art and papers of Mine Okubo, who grew up in Riverside.$t$, $t$https://en.wikipedia.org/wiki/Center_for_Social_Justice_and_Civil_Liberties$t$, $t$#452 hidden-pin row: osm_way118728049, stored in 679_-2348, 680_-2347, 680_-2348; containing tile 680_-2348 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
